mapper.update:
UPDATE sys_data_source_config SET config_name = #{configName}, url = #{url}, username = #{username},
    password_encrypted = #{passwordEncrypted}, max_active = #{maxActive}, target_services = #{targetServices},
    remark = #{remark}, version = version + 1, update_by = #{updateBy}, update_time = #{updateTime}
WHERE tenant_id = #{tenantId} AND config_id = #{configId} AND deleted = 0 AND version = #{version}

UPDATE sys_data_source_config SET status = #{status}, target_services = #{targetServices},
    version = version + 1, update_by = #{operator}, update_time = #{now}
WHERE tenant_id = #{tenantId} AND config_id = #{configId} AND deleted = 0 AND version = #{version}

UPDATE sys_data_source_registration SET status = #{status}, error_code = #{errorCode},
    checked_time = #{now}, update_by = 'reconcile', update_time = #{now}
WHERE tenant_id = #{tenantId} AND config_id = #{configId} AND service_name = #{serviceName}
    AND instance_key = #{instanceKey}
    AND (checked_time < #{before} OR (status = 'STALE' AND error_code = 'PENDING'))
